try (var processor = Executors.newVirtualThreadPerTaskExecutor()) {
    try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
        for (Command c : queuedCommands) {                 // macro: one unit of work
            scope.fork(() -> { c.execute(receiver); return null; });
        }
        scope.join();                                      // structured, not fire-and-forget
        scope.throwIfFailed();
    }
}   // close() waits for all commands to finish
